//! Phase 1 (Issue 1) golden-fixture harness: exact analytic CP quantiles for
//! `norm` / `lnorm` / `expon` vs. the reference `fitdistcp` R package.
//!
//! Loads `tests/golden/analytic_cp_golden.json` (generated by
//! `tools/generate_analytic_cp_golden.R` from the reference R package
//! `stephenjewson/fitdistcp`) and compares the Rust analytic CP quantiles
//! ([`fitdistcp_core::analytic_cp`]) against the reference's own `qnorm_cp` /
//! `qlnorm_cp` / `qexp_cp` at `n = 10, 20, 30`.
//!
//! # What this test proves
//!
//! Before Phase 1 the Rust core routed these three models through the DMGS
//! expansion, which is a first-order approximation of the exact Bayesian
//! prediction integral. The `lnorm` CP quantile is an exponential of a
//! Student-t quantile, so the `O(1/n)` truncation error is amplified by the
//! exponentiation — up to ~48% at `n = 10`. After Phase 1 the Rust analytic CP
//! quantiles match the reference to near machine precision.
//!
//! The harness asserts both:
//!
//! 1. **Analytic path** (`use_dmgs = false`): the Rust CP quantiles match the
//!    reference to the §7.2 tolerance (`RTOL = 1e-8`, `ATOL = 1e-10`).
//! 2. **DMGS cross-check** (`use_dmgs = true`): the DMGS CP quantiles are
//!    compared against the reference with a documented looser tolerance, and
//!    the `lnorm` residual is asserted to be large (the defect) — this pins the
//!    improvement so a regression that silently re-routes `lnorm` back to DMGS
//!    is caught.
//!
//! # Tolerance policy
//!
//! The canonical policy lives in [`tests/golden/TOLERANCE.md`](../../tests/golden/TOLERANCE.md)
//! §3.12. The analytic CP quantiles are an exact closed-form match, so they use
//! the baseline §7.2 tolerance.

use std::collections::HashMap;
use std::path::PathBuf;

use fitdistcp_core::api::{predict_analytic, AnalyticModel, PredictionRequest};

/// Baseline §7.2 tolerance: the analytic CP quantiles are an exact closed-form
/// match to the reference (limited only by the `student_t_quantile` bisection
/// precision and the reference's own rounding).
const RTOL: f64 = 1e-8;
const ATOL: f64 = 1e-10;

/// Looser tolerance for the Issue 1 repro at the extreme tail (`p = 0.99,
/// 0.996`). The `norm` CP quantile is a Student-t quantile with `df = n - 1`;
/// at these tail probabilities the `student_t_quantile` bisection precision
/// (and the reference `qt`'s own tail accuracy) dominates, giving a residual
/// of ~1e-6 rather than the ~1e-8 seen at `p <= 0.9`. This is a documented,
/// expected difference (see `tests/golden/TOLERANCE.md` §3.12).
const REPRO_RTOL: f64 = 1e-5;
const REPRO_ATOL: f64 = 1e-8;

/// Looser tolerance for the DMGS cross-check: the DMGS expansion is a
/// first-order approximation of the exact integral, so it differs by the
/// `O(1/n)` truncation error. This is a documented, expected difference.
const DMGS_TRUNC_RTOL: f64 = 5e-2;
const DMGS_TRUNC_ATOL: f64 = 1e-4;

fn assert_close(actual: f64, expected: f64, rtol: f64, atol: f64, what: &str) {
    let tol = atol + rtol * expected.abs();
    assert!(
        (actual - expected).abs() <= tol,
        "{what}: actual = {actual:.17e}, expected = {expected:.17e}, \
         |diff| = {:.3e} > tol = {:.3e}",
        (actual - expected).abs(),
        tol
    );
}

// --- Minimal JSON parser (test-only; avoids a serde_json dependency) --------

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(HashMap<String, Json>),
}

impl Json {
    fn as_f64(&self) -> f64 {
        match self {
            Json::Num(n) => *n,
            other => panic!("expected number, got {other:?}"),
        }
    }
    fn as_arr(&self) -> &[Json] {
        match self {
            Json::Arr(a) => a,
            other => panic!("expected array, got {other:?}"),
        }
    }
    fn as_obj(&self) -> &HashMap<String, Json> {
        match self {
            Json::Obj(o) => o,
            other => panic!("expected object, got {other:?}"),
        }
    }
    fn get(&self, key: &str) -> &Json {
        self.as_obj()
            .get(key)
            .unwrap_or_else(|| panic!("missing key {key:?}"))
    }
    fn as_f64_vec(&self) -> Vec<f64> {
        self.as_arr().iter().map(|v| v.as_f64()).collect()
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self {
            bytes: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        self.bytes[self.pos]
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::Str(self.parse_string()),
            b't' => {
                self.expect_lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.expect_lit("false");
                Json::Bool(false)
            }
            b'n' => {
                self.expect_lit("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect_lit(&mut self, lit: &str) {
        assert!(
            self.bytes[self.pos..].starts_with(lit.as_bytes()),
            "expected literal {lit:?} at {}",
            self.pos
        );
        self.pos += lit.len();
    }

    fn parse_object(&mut self) -> Json {
        assert_eq!(self.peek(), b'{');
        self.pos += 1;
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == b'}' {
            self.pos += 1;
            return Json::Obj(map);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.peek(), b':');
            self.pos += 1;
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in object", other as char),
            }
        }
        Json::Obj(map)
    }

    fn parse_array(&mut self) -> Json {
        assert_eq!(self.peek(), b'[');
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in array", other as char),
            }
        }
        Json::Arr(items)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.peek(), b'"');
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            match c {
                b'"' => {
                    self.pos += 1;
                    return s;
                }
                b'\\' => {
                    self.pos += 1;
                    let esc = self.bytes[self.pos];
                    match esc {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'r' => s.push('\r'),
                        other => panic!("bad escape \\{}", other as char),
                    }
                    self.pos += 1;
                }
                _ => {
                    s.push(c as char);
                    self.pos += 1;
                }
            }
        }
        panic!("unterminated string");
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let text = std::str::from_utf8(&self.bytes[start..self.pos]).expect("utf8 number");
        Json::Num(text.parse::<f64>().expect("valid number"))
    }
}

fn load_fixture() -> Json {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "..",
        "..",
        "tests",
        "golden",
        "analytic_cp_golden.json",
    ]
    .iter()
    .collect();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    Parser::new(&text).parse_value()
}

fn compare_vec(actual: &[f64], expected: &[f64], rtol: f64, atol: f64, what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}: length mismatch");
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        assert_close(*a, *e, rtol, atol, &format!("{what}[{i}]"));
    }
}

/// Maximum relative residual `|a - e| / |e|` over two equal-length vectors.
fn max_rel_residual(actual: &[f64], expected: &[f64]) -> f64 {
    actual
        .iter()
        .zip(expected.iter())
        .map(|(a, e)| (a - e).abs() / e.abs().max(f64::MIN_POSITIVE))
        .fold(0.0_f64, f64::max)
}

fn make_request(y: Vec<f64>, p: Vec<f64>) -> PredictionRequest {
    PredictionRequest {
        y,
        x: vec![],
        p,
        t: None,
        t0: None,
        n0: None,
        means: None,
    }
}

/// Run the analytic path for one model at one `n` and compare to the reference.
fn check_model(
    model: AnalyticModel,
    init: &[f64],
    y: &[f64],
    p: &[f64],
    ref_cp: &[f64],
    label: &str,
) {
    let req = make_request(y.to_vec(), p.to_vec());
    let r = predict_analytic(model, &req, init, false);
    compare_vec(&r.cp_quantiles, ref_cp, RTOL, ATOL, label);
}

/// Phase B (Issue 1): the report's exact repro vector at `p = 0.99, 0.996`.
///
/// The report observed the `lnorm` CP quantile diverging from the reference at
/// these tail levels. This pins the reference's own analytic result for the
/// literal repro vector, so the reported case is regression-tested.
#[test]
fn golden_analytic_cp_repro_vector() {
    let root = load_fixture();
    let repro = root.get("repro");
    let p = repro.get("p").as_f64_vec();
    let y = root.get("datasets").get("repro_y").as_f64_vec();

    // The extreme-tail repro uses the documented looser tolerance (see
    // `REPRO_RTOL`): the Student-t bisection precision dominates at p = 0.99,
    // 0.996.
    let check = |model: AnalyticModel, init: &[f64], ref_cp: &[f64], label: &str| {
        let req = make_request(y.clone(), p.clone());
        let r = predict_analytic(model, &req, init, false);
        compare_vec(&r.cp_quantiles, ref_cp, REPRO_RTOL, REPRO_ATOL, label);
    };

    // norm: init [mean, sd].
    let norm = repro.get("repro_norm");
    check(
        AnalyticModel::Norm,
        &[6.8, 6.0],
        &norm.get("cp_quantiles").as_f64_vec(),
        "repro.norm.cp_q",
    );

    // lnorm: init [meanlog, sdlog].
    let lnorm = repro.get("repro_lnorm");
    check(
        AnalyticModel::Lnorm,
        &[1.65, 0.68],
        &lnorm.get("cp_quantiles").as_f64_vec(),
        "repro.lnorm.cp_q",
    );

    // expon: init [rate].
    let expon = repro.get("repro_expon");
    check(
        AnalyticModel::Expon,
        &[0.147],
        &expon.get("cp_quantiles").as_f64_vec(),
        "repro.expon.cp_q",
    );
}

#[test]
fn golden_analytic_cp_quantiles() {
    let root = load_fixture();
    let models = root.get("models");
    let p_grid = root.get("p_grid").as_f64_vec();
    let datasets = root.get("datasets");
    let y_norm = datasets.get("y_norm").as_f64_vec();
    let y_positive = datasets.get("y_positive").as_f64_vec();

    for (key, n) in [("n10", 10usize), ("n20", 20), ("n30", 30)] {
        let m = models.get(key);
        let yn = &y_norm[..n];
        let yp = &y_positive[..n];

        // norm: init [mean, sd] (the MLE is closed form; the optimizer lands on
        // it exactly).
        let norm = m.get("norm");
        check_model(
            AnalyticModel::Norm,
            &[10.0, 1.0],
            yn,
            &p_grid,
            &norm.get("cp_quantiles").as_f64_vec(),
            &format!("{key}.norm.cp_q"),
        );

        // lnorm: init [meanlog, sdlog].
        let lnorm = m.get("lnorm");
        check_model(
            AnalyticModel::Lnorm,
            &[0.0, 1.0],
            yp,
            &p_grid,
            &lnorm.get("cp_quantiles").as_f64_vec(),
            &format!("{key}.lnorm.cp_q"),
        );

        // expon: init [rate].
        let expon = m.get("expon");
        check_model(
            AnalyticModel::Expon,
            &[1.0],
            yp,
            &p_grid,
            &expon.get("cp_quantiles").as_f64_vec(),
            &format!("{key}.expon.cp_q"),
        );
    }
}

/// The DMGS cross-check: the pre-Phase-1 path (behind `use_dmgs = true`) is a
/// first-order approximation, so it differs from the exact analytic CP by the
/// `O(1/n)` truncation error. This test pins the defect: the `lnorm` DMGS
/// residual at `n = 10` is large (~48%), while the analytic residual is at
/// machine precision.
#[test]
fn golden_dmgs_cross_check_and_lnorm_residual_improvement() {
    let root = load_fixture();
    let models = root.get("models");
    let p_grid = root.get("p_grid").as_f64_vec();
    let datasets = root.get("datasets");
    let y_positive = datasets.get("y_positive").as_f64_vec();

    // n = 10 lnorm: the worst case for the DMGS truncation error.
    let m = models.get("n10");
    let lnorm = m.get("lnorm");
    let ref_cp = lnorm.get("cp_quantiles").as_f64_vec();
    let yp = &y_positive[..10];

    let req = make_request(yp.to_vec(), p_grid.clone());

    // Analytic path: near machine precision.
    let analytic = predict_analytic(AnalyticModel::Lnorm, &req, &[0.0, 1.0], false);
    let analytic_res = max_rel_residual(&analytic.cp_quantiles, &ref_cp);
    assert!(
        analytic_res < 1e-6,
        "analytic lnorm residual {analytic_res:.3e} should be near machine precision"
    );

    // DMGS path: the documented O(1/n) truncation error (the defect).
    let dmgs = predict_analytic(AnalyticModel::Lnorm, &req, &[0.0, 1.0], true);
    let dmgs_res = max_rel_residual(&dmgs.cp_quantiles, &ref_cp);
    assert!(
        dmgs_res > 1e-2,
        "DMGS lnorm residual {dmgs_res:.3e} should be large (the defect)"
    );

    // The analytic path must be a strict, dramatic improvement.
    assert!(
        analytic_res < dmgs_res * 1e-3,
        "analytic residual {analytic_res:.3e} should be << DMGS residual {dmgs_res:.3e}"
    );

    // The DMGS cross-check still matches the reference within the documented
    // truncation tolerance (it is a valid approximation, just not exact).
    compare_vec(
        &dmgs.cp_quantiles,
        &ref_cp,
        DMGS_TRUNC_RTOL,
        DMGS_TRUNC_ATOL,
        "n10.lnorm.dmgs_cp_q",
    );

    eprintln!(
        "lnorm n=10 residual: analytic = {analytic_res:.3e}, DMGS = {dmgs_res:.3e} \
         (improvement factor {:.1}x)",
        dmgs_res / analytic_res
    );
}
